(7747796, 1279151, 83313, '<td valign="top">Skipping the vote on this one, since I was standing a few feet from you. Good luck with it!</td>', 'Skipping the vote on this one, since I was standing a few feet from you. Good luck with it!', '2023-06-05 01:57:07.000000', NULL, 1),
(7747848, 1279588, 89774, '<td valign="top">I would love to have seen this taken at a different time of day (either early morning or sunset) to see how the light casts on those buildings but I also understand that life doesn''t always allow for that :)</td>', 'I would love to have seen this taken at a different time of day (either early morning or sunset) to see how the light casts on those buildings but I also understand that life doesn''t always allow for that :)', '2023-06-05 11:17:30.000000', NULL, 1),
(7747850, 1279803, 89774, '<td valign="top">I recognize this from the trees challenge and I am still wondering what the object is under the sun... if that wasn''t there (which I realize you have no control over), this would be a 10 for me.</td>', 'I recognize this from the trees challenge and I am still wondering what the object is under the sun... if that wasn''t there (which I realize you have no control over), this would be a 10 for me.', '2023-06-05 11:22:29.000000', NULL, 1),
(7747851, 1279767, 89774, '<td valign="top">I would love to see this cropped on the left side up to the first tree to remove the building and bench as that would draw my eye into the picture better, but great shot!</td>', 'I would love to see this cropped on the left side up to the first tree to remove the building and bench as that would draw my eye into the picture better, but great shot!', '2023-06-05 11:23:55.000000', NULL, 1),
