(7747853, 1279598, 89774, '<td valign="top">Oh how I wish the water was flat all the way across to capture all of those clouds'' reflection. Good capture though!</td>', 'Oh how I wish the water was flat all the way across to capture all of those clouds'' reflection. Good capture though!', '2023-06-05 11:30:12.000000', NULL, 1),
(7747909, 1279584, 122678, '<td valign="top">This is stunning, one of the most beautiful sunset images I have seen.<br/>I love the bike, the reflection, stilts and all the other interesting components of this image.</td>', 'This is stunning, one of the most beautiful sunset images I have seen.I love the bike, the reflection, stilts and all the other interesting components of this image.', '2023-06-05 15:14:19.000000', NULL, 1),
(7747961, 1279598, 9668, '<td valign="top">Nice reflection and composition. Odd to me that the clouds above are darker than the reflection, feels a bit unnatural to me.</td>', 'Nice reflection and composition. Odd to me that the clouds above are darker than the reflection, feels a bit unnatural to me.', '2023-06-05 18:27:51.000000', NULL, 1),
